from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        # Broad strike and expiry range; entry logic performs the exact selection.
        option.SetFilter(-100, 100, timedelta(0), timedelta(days=730))

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None

        self.five_minute = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.five_minute)

        self.pending_entry = False
        self.pending_entry_bar_end = None

        self.held_symbol = None
        self.entry_fill_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.no_new_entry_date = None

    def OnFiveMinuteBar(self, sender, bar):
        # Actual consolidated bars only: missing minute data is never synthesized.
        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if self.fast.IsReady and self.slow.IsReady:
            current_fast = self.fast.Current.Value
            current_slow = self.slow.Current.Value

            is_bullish_cross = (
                self.previous_fast is not None
                and self.previous_fast <= self.previous_slow
                and current_fast > current_slow
            )

            end_time = bar.EndTime
            eligible_time = (
                (end_time.hour > 9 or (end_time.hour == 9 and end_time.minute >= 45))
                and (end_time.hour < 14 or (end_time.hour == 14 and end_time.minute <= 30))
            )

            if is_bullish_cross and eligible_time:
                self.pending_entry = True
                self.pending_entry_bar_end = end_time

            self.previous_fast = current_fast
            self.previous_slow = current_slow

    def OnData(self, slice):
        self._handle_expiration_safety()

        if self._has_open_position():
            self._evaluate_exits(slice)

        if self.pending_entry:
            self.pending_entry = False
            self._try_enter(slice)

    def _try_enter(self, slice):
        if self.no_new_entry_date == self.Time.date():
            return

        if self._has_open_position() or self.entry_order_id is not None:
            return

        if self.spy not in slice.Bars:
            self.Debug("Entry skipped: no current SPY TradeBar.")
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Entry skipped: no option chain in current Slice.")
            return

        spot = slice.Bars[self.spy].Close
        today = self.Time.date()

        contracts = []
        for chain in chains:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue
                if (contract.Expiry.date() - today).days < 7:
                    continue
                contracts.append(contract)

        if not contracts:
            self.Debug("Entry skipped: no call expiration at least 7 calendar days away.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in contracts)
        minimum_strike = spot * 1.01

        eligible = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not eligible:
            self.Debug(
                "Entry skipped: no call at the nearest eligible expiry meets the 1% OTM strike rule."
            )
            return

        selected = min(eligible, key=lambda c: (c.Strike, str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)

        if ticket is not None:
            self.entry_order_id = ticket.OrderId
            self.Debug(
                f"Entry submitted: {selected.Symbol} expiry {selected.Expiry.date()} "
                f"strike {selected.Strike}."
            )

    def _evaluate_exits(self, slice):
        if self.held_symbol is None or not self.Portfolio[self.held_symbol].Invested:
            return

        expiry_date = self.held_symbol.ID.Date.date()

        # Never intentionally hold into expiration.
        if self.Time.date() >= expiry_date:
            self.no_new_entry_date = self.Time.date()
            self.Debug(f"Expiration safety exit submitted: {self.held_symbol}.")
            self._submit_exit("expiration safety")
            return

        if (
            self.Time.date() == self._previous_trading_day(expiry_date)
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self.Debug(f"15:45 time-stop exit submitted: {self.held_symbol}.")
            self._submit_exit("time stop")
            return

        midpoint = self._current_midpoint_from_slice(slice, self.held_symbol)
        if (
            midpoint is not None
            and self.entry_fill_price is not None
            and midpoint >= self.entry_fill_price * 1.50
        ):
            self.Debug(
                f"Profit-target exit submitted: {self.held_symbol}; "
                f"midpoint {midpoint:.2f}, entry {self.entry_fill_price:.2f}."
            )
            self._submit_exit("profit target")

    def _current_midpoint_from_slice(self, slice, symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol != symbol:
                    continue

                bid = contract.BidPrice
                ask = contract.AskPrice
                if bid is None or ask is None or bid <= 0 or ask <= 0:
                    return None

                return (bid + ask) / 2.0

        return None

    def _submit_exit(self, reason):
        if self.held_symbol is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        # Remove any outstanding order for this contract before submitting the exit.
        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            self.Transactions.CancelOrder(order.Id, f"Replacing with {reason} exit.")

        ticket = self.MarketOrder(self.held_symbol, -quantity)
        if ticket is not None:
            self.exit_order_id = ticket.OrderId

    def _has_open_position(self):
        return (
            self.held_symbol is not None
            and self.Portfolio[self.held_symbol].Invested
        )

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def _handle_expiration_safety(self):
        if not self._has_open_position():
            return

        expiry_date = self.held_symbol.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.no_new_entry_date = self.Time.date()
            if self.exit_order_id is None:
                self.Debug(f"Expiration processing detected open option: {self.held_symbol}.")
                self._submit_exit("expiration processing")

    def OnOrderEvent(self, order_event):
        event_type = str(order_event.OrderType)
        message = (order_event.Message or "").lower()

        if (
            "exercise" in event_type.lower()
            or "assignment" in event_type.lower()
            or "exercise" in message
            or "assignment" in message
        ):
            self.Debug(
                f"Unexpected option exercise/assignment event: "
                f"{order_event.Symbol}, {order_event.Status}, {order_event.Message}"
            )

        if (
            self.entry_order_id is not None
            and order_event.OrderId == self.entry_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_fill_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_symbol} at {self.entry_fill_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None
                self.Debug(f"Entry order did not fill: {order_event.Status}.")

        if (
            self.exit_order_id is not None
            and order_event.OrderId == self.exit_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}.")
                self.exit_order_id = None
                self.held_symbol = None
                self.entry_fill_price = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None
                self.Debug(f"Exit order did not fill: {order_event.Status}.")
