from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        ).Symbol

        self.option_symbol = self.AddOption("SPY", Resolution.Minute).Symbol
        self.Securities[self.option_symbol].SetFilter(
            -100, 100,
            timedelta(days=0),
            timedelta(days=365)
        )

        self._closes = []
        self._previous_fast = None
        self._previous_slow = None
        self._pending_entry_signal = False

        self._held_symbol = None
        self._entry_price = None
        self._entry_order_id = None
        self._exit_order_id = None
        self._blocked_entry_date = None

        consolidator = TradeBarConsolidator(self._five_minute_calendar)
        consolidator.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def _five_minute_calendar(self, time):
        start = time.replace(
            minute=(time.minute // 5) * 5,
            second=0,
            microsecond=0
        )
        return CalendarInfo(start, timedelta(minutes=5))

    def _on_five_minute_bar(self, sender, bar):
        self._pending_entry_signal = False

        self._closes.append(float(bar.Close))
        if len(self._closes) > 20:
            self._closes.pop(0)

        if len(self._closes) < 20:
            return

        fast = sum(self._closes[-5:]) / 5.0
        slow = sum(self._closes) / 20.0

        crossed_up = (
            self._previous_fast is not None and
            self._previous_slow is not None and
            self._previous_fast <= self._previous_slow and
            fast > slow
        )

        self._previous_fast = fast
        self._previous_slow = slow

        bar_time = bar.EndTime.time()
        eligible_time = (
            bar_time >= datetime.strptime("09:45", "%H:%M").time() and
            bar_time <= datetime.strptime("14:30", "%H:%M").time()
        )

        if crossed_up and eligible_time:
            self._pending_entry_signal = True

    def OnData(self, data):
        today = self.Time.date()

        if self._held_symbol is not None:
            self._handle_expiration_safety(today)
            self._handle_time_stop(today)
            self._handle_profit_target(data)

        if self._pending_entry_signal:
            self._pending_entry_signal = False
            self._try_enter(data)

    def _try_enter(self, data):
        if self._blocked_entry_date == self.Time.date():
            return

        if self._held_symbol is not None:
            return

        if self._entry_order_id is not None:
            return

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is None or spy_bar.Close <= 0:
            self.Debug(f"{self.Time}: Skipped entry: no current SPY bar.")
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{self.Time}: Skipped entry: no option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.Debug(f"{self.Time}: Skipped entry: no expiry at least 7 calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = float(spy_bar.Close) * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: Skipped entry: no qualifying call for {selected_expiry}."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        self._entry_order_id = ticket.OrderId
        self.Debug(
            f"{self.Time}: Submitted entry for {selected.Symbol}, "
            f"expiry {selected_expiry}, strike {selected.Strike}."
        )

    def _handle_profit_target(self, data):
        if self._entry_price is None or self._exit_order_id is not None:
            return

        quote_bar = data.QuoteBars.get(self._held_symbol)
        if quote_bar is None or quote_bar.Bid is None or quote_bar.Ask is None:
            return

        bid = float(quote_bar.Bid.Close)
        ask = float(quote_bar.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self._entry_price * 1.50:
            self._submit_exit("50% profit target")

    def _handle_time_stop(self, today):
        if self._exit_order_id is not None:
            return

        if self.Time.hour != 15 or self.Time.minute != 45:
            return

        expiry = self._held_symbol.ID.Date.date()
        if self._is_previous_trading_day(today, expiry):
            self._submit_exit("15:45 pre-expiration time stop")

    def _handle_expiration_safety(self, today):
        expiry = self._held_symbol.ID.Date.date()

        if today >= expiry:
            self._blocked_entry_date = today
            if self._exit_order_id is None:
                self._submit_exit("expiration safety liquidation")

    def _is_previous_trading_day(self, current_date, expiration_date):
        next_open_date = current_date + timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(next_open_date):
            next_open_date += timedelta(days=1)

        return next_open_date == expiration_date

    def _submit_exit(self, reason):
        if self._held_symbol is None or self._exit_order_id is not None:
            return

        for order in self.Transactions.GetOpenOrders(self._held_symbol):
            self.Transactions.CancelOrder(order.Id, f"Replacing open exit: {reason}")

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self._held_symbol, -quantity)
        self._exit_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: Submitted exit for {self._held_symbol}: {reason}.")

    def OnOrderEvent(self, order_event):
        message = str(order_event.Message or "").lower()
        if "exercise" in message or "assignment" in message:
            self.Debug(
                f"{self.Time}: Unexpected exercise/assignment handling: "
                f"{order_event.Symbol} - {order_event.Message}"
            )

        if order_event.OrderId == self._entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self._held_symbol = order_event.Symbol
                self._entry_price = float(order_event.FillPrice)
                self._entry_order_id = None
                self.Debug(
                    f"{self.Time}: Entry filled for {order_event.Symbol} "
                    f"at {order_event.FillPrice}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"{self.Time}: Entry order did not fill: {order_event.Message}")
                self._entry_order_id = None

        if order_event.OrderId == self._exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
