    def _is_previous_trading_day(self, current_date, expiration_date):
        next_open_date = current_date + timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(next_open_date):
