from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
                                    .Strikes(-100, 100)
                                    .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.pending_crossover_end = None

        self.held_symbol = None
        self.held_expiry = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_fill_price = None
        self.no_entry_date = None

        consolidator = TradeBarConsolidator(self.FiveMinuteCalendar)
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy.Symbol, consolidator)

    def FiveMinuteCalendar(self, time):
        session_open = datetime(time.year, time.month, time.day, 9, 30)

        if time < session_open:
            return CalendarInfo(time, timedelta(minutes=5))

        interval = int((time - session_open).total_seconds() // 300)
        start = session_open + timedelta(minutes=5 * interval)
        return CalendarInfo(start, timedelta(minutes=5))

    def OnFiveMinuteBar(self, sender, bar):
        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value
        previous_slow = self.slow.Current.Value

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not previous_ready or not (self.fast.IsReady and self.slow.IsReady):
            return

        if previous_fast <= previous_slow and self.fast.Current.Value > self.slow.Current.Value:
            end_time = bar.EndTime.time()
            if end_time >= datetime(2000, 1, 1, 9, 45).time() and \
               end_time <= datetime(2000, 1, 1, 14, 30).time():
                self.pending_crossover_end = bar.EndTime

    def OnData(self, data):
        today = self.Time.date()

        self.ProcessExpirationProtection(today)

        if self.held_symbol is not None:
            self.ProcessPositionExit(data, today)
        elif self.pending_crossover_end is not None:
            self.TryEnterFromCurrentSlice(data, today)

        # A crossover is evaluated once only, using this current Slice.
        self.pending_crossover_end = None

    def ProcessExpirationProtection(self, today):
        if self.held_symbol is None or self.held_expiry is None:
            return

        if today >= self.held_expiry:
            self.no_entry_date = today
            if not self.HasOpenExitOrder():
                self.Debug(f"Expiration protection: liquidating {self.held_symbol}")
                self.SubmitExitOrder("expiration protection")

    def ProcessPositionExit(self, data, today):
        if self.held_symbol is None or not self.Portfolio[self.held_symbol].Invested:
            return

        if self.held_expiry is not None:
            prior_trading_day = self.PreviousSpyTradingDay(self.held_expiry)
            if today == prior_trading_day and self.Time.hour == 15 and self.Time.minute == 45:
                if not self.HasOpenExitOrder():
                    self.Debug(f"Time exit: liquidating {self.held_symbol}")
                    self.SubmitExitOrder("pre-expiration time stop")
                return

        if self.entry_fill_price is None or self.HasOpenExitOrder():
            return

        if not data.QuoteBars.ContainsKey(self.held_symbol):
            return

        quote = data.QuoteBars[self.held_symbol]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self.CancelOtherOpenExitOrders()
            self.Debug(
                f"Profit exit: liquidating {self.held_symbol}; "
                f"midpoint={midpoint:.2f}, entry={self.entry_fill_price:.2f}"
            )
            self.SubmitExitOrder("profit target")

    def TryEnterFromCurrentSlice(self, data, today):
        if self.no_entry_date == today:
            return

        if self.held_symbol is not None or self.HasOpenEntryOrder():
            return

        if not data.OptionChains.ContainsKey(self.option.Symbol):
            self.Debug("Skipped entry: no SPY option chain in current Slice.")
            return

        spot = self.Securities[self.spy.Symbol].Price
        if spot <= 0:
            self.Debug("Skipped entry: SPY price unavailable.")
            return

        chain = data.OptionChains[self.option.Symbol]
        minimum_expiry = today + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no SPY expiration at least 7 calendar days away.")
            return

        selected_expiry = expiries[0]
        minimum_strike = spot * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"Skipped entry: no call at or above 1% OTM for expiry {selected_expiry}."
            )
            return

        contract = sorted(candidates, key=lambda c: (c.Strike, str(c.Symbol)))[0]

        ticket = self.MarketOrder(contract.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.held_symbol = contract.Symbol
        self.held_expiry = contract.Expiry.date()
        self.entry_fill_price = None

        self.Debug(
            f"Entry submitted: {contract.Symbol}, expiry={self.held_expiry}, "
            f"strike={contract.Strike:.2f}"
        )

    def SubmitExitOrder(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted ({reason}): {self.held_symbol}")

    def PreviousSpyTradingDay(self, expiry):
        candidate = expiry - timedelta(days=1)
        hours = self.Securities[self.spy.Symbol].Exchange.Hours

        while not hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def HasOpenEntryOrder(self):
        if self.entry_order_id is None:
            return False

        order = self.Transactions.GetOrderById(self.entry_order_id)
        return order is not None and order.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def HasOpenExitOrder(self):
        if self.exit_order_id is None:
            return False

        order = self.Transactions.GetOrderById(self.exit_order_id)
        return order is not None and order.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def CancelOtherOpenExitOrders(self):
        if self.held_symbol is None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            if order.Quantity < 0 and order.Id != self.exit_order_id:
                self.Transactions.CancelOrder(order.Id)

    def OnOrderEvent(self, orderEvent):
        if orderEvent.OrderId == self.entry_order_id:
            if orderEvent.Status == OrderStatus.Filled:
                self.entry_fill_price = orderEvent.FillPrice
                self.Debug(
                    f"Entry filled: {self.held_symbol} at {self.entry_fill_price:.2f}"
                )
            elif orderEvent.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"Entry order did not fill: {orderEvent.Message}")
                self.entry_order_id = None
                if self.held_symbol is not None and not self.Portfolio[self.held_symbol].Invested:
                    self.held_symbol = None
                    self.held_expiry = None
                    self.entry_fill_price = None

        if orderEvent.OrderId == self.exit_order_id:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {self.held_symbol} at {orderEvent.FillPrice:.2f}")
                self.held_symbol = None
                self.held_expiry = None
                self.entry_fill_price = None
                self.entry_order_id = None
                self.exit_order_id = None
