from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option_symbol = self.AddOption("SPY", Resolution.Minute).Symbol
        self.OptionChainProvider.SetOptionFilter(
            self.option_symbol,
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._minute_bars = {}
        self._minute_bar_date = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_contract = None
        self.entry_fill_price = None
        self.expiration_entry_block_date = None

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.AfterMarketOpen(self.spy, 0),
            self.ExpirationSafetyCheck
        )

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self.PreExpirationTimeStop
        )

    def OnData(self, slice):
        self._process_expiration_day_safety()

        # The time stop is scheduled independently, but profit checks occur
        # on every minute Slice while a position is held.
        self._check_profit_target(slice)

        if self.Time.date() != self._minute_bar_date:
            self._minute_bars = {}
            self._minute_bar_date = self.Time.date()

        if self.spy in slice.Bars:
            bar = slice.Bars[self.spy]
            self._minute_bars[bar.EndTime] = bar

        if self._is_five_minute_close(self.Time):
            bullish_crossover = self._complete_five_minute_bar(self.Time)

            if bullish_crossover and self._entry_time_is_eligible(self.Time):
                self._try_enter(slice)

    def _is_five_minute_close(self, timestamp):
        current_time = timestamp.time()
        return (
            time(9, 35) <= current_time <= time(16, 0)
            and timestamp.minute % 5 == 0
        )

    def _complete_five_minute_bar(self, end_time):
        expected_end_times = [
            end_time - timedelta(minutes=offset)
            for offset in range(4, -1, -1)
        ]

        bars = [self._minute_bars.get(timestamp) for timestamp in expected_end_times]

        # Remove all data belonging to this completed interval. If any minute
        # is absent, no synthetic five-minute bar is produced.
        for timestamp in expected_end_times:
            self._minute_bars.pop(timestamp, None)

        if any(bar is None for bar in bars):
            return False

        prior_fast = self.fast.Current.Value if self.fast.IsReady else None
        prior_slow = self.slow.Current.Value if self.slow.IsReady else None

        close = bars[-1].Close
        point = IndicatorDataPoint(end_time, close)
        self.fast.Update(point)
        self.slow.Update(point)

        if prior_fast is None or prior_slow is None:
            return False

        return (
            self.fast.IsReady
            and self.slow.IsReady
            and prior_fast <= prior_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

    def _entry_time_is_eligible(self, timestamp):
        return time(9, 45) <= timestamp.time() <= time(14, 30)

    def _try_enter(self, slice):
        if self.expiration_entry_block_date == self.Time.date():
            return

        if self.entry_ticket is not None:
            return

        if self.held_contract is not None and self.Portfolio[self.held_contract].Quantity != 0:
            return

        if self.option_symbol not in slice.OptionChains:
            self.Debug(f"{self.Time}: skipped call entry; no SPY option chain in Slice")
            return

        if self.spy not in slice.Bars:
            self.Debug(f"{self.Time}: skipped call entry; no current SPY price in Slice")
            return

        chain = slice.OptionChains[self.option_symbol]
        spy_price = slice.Bars[self.spy].Close
        algorithm_date = self.Time.date()

        valid_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= algorithm_date + timedelta(days=7)
        })

        if not valid_expirations:
            self.Debug(f"{self.Time}: skipped call entry; no expiration at least 7 calendar days away")
            return

        selected_expiry = valid_expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: skipped call entry; no qualifying call for "
                f"{selected_expiry} at SPY {spy_price:.2f}"
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"{self.Time}: submitted entry for 1 {selected.Symbol}; "
            f"expiry {selected.Expiry.date()}, strike {selected.Strike}"
        )

    def _check_profit_target(self, slice):
        if self.held_contract is None:
            return

        if self.Portfolio[self.held_contract].Quantity <= 0:
            return

        if self.entry_fill_price is None or self.exit_ticket is not None:
            return

        if self.held_contract not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.held_contract]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self._submit_exit("50% profit target")

    def PreExpirationTimeStop(self):
        if self.held_contract is None or self.Portfolio[self.held_contract].Quantity <= 0:
            return

        expiry_date = self.held_contract.ID.Date.date()
        next_trading_open = self.Securities[self.spy].Exchange.Hours.GetNextMarketOpen(
            self.Time,
            False
        )

        if next_trading_open.date() == expiry_date:
            self._submit_exit("15:45 pre-expiration time stop")

    def ExpirationSafetyCheck(self):
        self._process_expiration_day_safety()

    def _process_expiration_day_safety(self):
        if self.held_contract is None or self.Portfolio[self.held_contract].Quantity <= 0:
            return

        expiry_date = self.held_contract.ID.Date.date()
        if expiry_date <= self.Time.date():
            self.expiration_entry_block_date = self.Time.date()
            self._submit_exit("expiration-day safety liquidation")

    def _submit_exit(self, reason):
        if self.held_contract is None or self.exit_ticket is not None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id, f"Replacing open exit order: {reason}")

        self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
        self.Debug(f"{self.Time}: submitted exit for {self.held_contract}; {reason}")

    def OnOrderEvent(self, order_event):
        if order_event.OrderType == OrderType.OptionExercise:
            self.Debug(
                f"{self.Time}: unexpected option exercise/assignment event for "
                f"{order_event.Symbol}: {order_event.Status}"
            )

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.entry_fill_price = order_event.FillPrice
                self.entry_ticket = None
                self.Debug(
                    f"{self.Time}: entry filled for {self.held_contract} at "
                    f"{self.entry_fill_price:.2f}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.Debug(f"{self.Time}: entry order did not fill: {order_event.Status}")
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: exit filled for {order_event.Symbol} at "
                    f"{order_event.FillPrice:.2f}"
                )
                self.exit_ticket = None
                self.held_contract = None
                self.entry_fill_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.Debug(f"{self.Time}: exit order did not fill: {order_event.Status}")
                self.exit_ticket = None
