from AlgorithmImports import *
from collections import deque
from datetime import timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(lambda universe: universe.Strikes(-100, 100).Expiration(0, 730))
        self.option_symbol = option.Symbol

        self._five_minute_closes = deque(maxlen=20)
        self._previous_fast = None
        self._previous_slow = None

        self._active_bar_end = None
        self._active_bar_closes = {}

        self._held_contract = None
        self._entry_order_id = None
        self._exit_order_id = None
        self._entry_fill_price = None
        self._no_entry_date = None

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self._time_stop
        )

    def OnData(self, data: Slice):
        self._handle_expiration(data)

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is not None:
            self._update_five_minute_bars(spy_bar, data)

        self._check_profit_target(data)

    def _update_five_minute_bars(self, bar: TradeBar, data: Slice):
        end_time = bar.EndTime

        # With regular-hours SPY minute data, bars end from 09:31 through 16:00.
        if end_time.time() < time(9, 31) or end_time.time() > time(16, 0):
            return

        minutes_to_boundary = (5 - end_time.minute % 5) % 5
        group_end = end_time + timedelta(
            minutes=minutes_to_boundary,
            seconds=-end_time.second,
            microseconds=-end_time.microsecond
        )

        if self._active_bar_end is not None and group_end != self._active_bar_end:
            # A previous interval did not receive its final minute; discard it.
            self._active_bar_closes.clear()

        if group_end != self._active_bar_end:
            self._active_bar_end = group_end
            self._active_bar_closes = {}

        self._active_bar_closes[end_time] = bar.Close

        if end_time != group_end:
            return

        required_ends = [
            group_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        # Never synthesize or forward-fill an incomplete five-minute bar.
        if not all(timestamp in self._active_bar_closes for timestamp in required_ends):
            self._active_bar_closes.clear()
            return

        five_minute_close = self._active_bar_closes[group_end]
        self._active_bar_closes.clear()

        self._five_minute_closes.append(five_minute_close)
        if len(self._five_minute_closes) < 20:
            return

        closes = list(self._five_minute_closes)
        fast = sum(closes[-5:]) / 5.0
        slow = sum(closes) / 20.0

        bullish_cross = (
            self._previous_fast is not None
            and self._previous_slow is not None
            and self._previous_fast <= self._previous_slow
            and fast > slow
        )

        self._previous_fast = fast
        self._previous_slow = slow

        if not bullish_cross:
            return

        if time(9, 45) <= group_end.time() <= time(14, 30):
            self._try_enter(data, five_minute_close)

    def _try_enter(self, data: Slice, spy_price: float):
        if self._no_entry_date == self.Time.date():
            return

        if self._held_contract is not None and self.Portfolio[self._held_contract].Invested:
            return

        if self._entry_order_is_open():
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{self.Time}: Entry skipped: no SPY option chain.")
            return

        today = self.Time.date()
        eligible = [
            contract for contract in chain
            if contract.Expiry.date() >= today + timedelta(days=7)
        ]

        if not eligible:
            self.Debug(f"{self.Time}: Entry skipped: no expiration at least 7 calendar days away.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in eligible)
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(f"{self.Time}: Entry skipped: no qualifying call at selected expiration.")
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)
        self._entry_order_id = ticket.OrderId
        self.Debug(
            f"{self.Time}: Entry submitted: {selected.Symbol}, "
            f"expiry {selected.Expiry.date()}, strike {selected.Strike}."
        )

    def _check_profit_target(self, data: Slice):
        if self._held_contract is None or not self.Portfolio[self._held_contract].Invested:
            return

        if self._exit_order_is_open() or self._entry_fill_price is None:
            return

        contract = self._find_contract_in_slice(data, self._held_contract)
        if contract is None or contract.BidPrice <= 0 or contract.AskPrice <= 0:
            return

        midpoint = (contract.BidPrice + contract.AskPrice) / 2.0
        if midpoint >= 1.50 * self._entry_fill_price:
            self._submit_exit("profit target")

    def _time_stop(self):
        if self._held_contract is None or not self.Portfolio[self._held_contract].Invested:
            return

        expiry = self._held_contract.ID.Date.date()
        previous_trading_day = self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(
            self._held_contract.ID.Date
        ).date()

        if self.Time.date() == previous_trading_day:
            self._submit_exit("15:45 pre-expiration time stop")

    def _handle_expiration(self, data: Slice):
        if self._held_contract is None or not self.Portfolio[self._held_contract].Invested:
            return

        expiry_date = self._held_contract.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self._no_entry_date = self.Time.date()
            if not self._exit_order_is_open():
                self._submit_exit("expiration-day protection")

    def _submit_exit(self, reason: str):
        if self._held_contract is None or self._exit_order_is_open():
            return

        for ticket in self.Transactions.GetOpenOrderTickets():
            if ticket.Symbol == self._held_contract and ticket.OrderId != self._entry_order_id:
                ticket.Cancel("Replacing open exit order")

        quantity = self.Portfolio[self._held_contract].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self._held_contract, -quantity)
        self._exit_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: Exit submitted ({reason}): {self._held_contract}.")

