        if spy_bar is not None:
            self._update_five_minute_bars(spy_bar, data)

        self._check_profit_target(data)

    def _update_five_minute_bars(self, bar: TradeBar, data: Slice):
        end_time = bar.EndTime

        # With regular-hours SPY minute data, bars end from 09:31 through 16:00.
        if end_time.time() < time(9, 31) or end_time.time() > time(16, 0):
            return

        minutes_to_boundary = (5 - end_time.minute % 5) % 5
        group_end = end_time + timedelta(
            minutes=minutes_to_boundary,
            seconds=-end_time.second,
            microseconds=-end_time.microsecond
        )

        if self._active_bar_end is not None and group_end != self._active_bar_end:
            # A previous interval did not receive its final minute; discard it.
            self._active_bar_closes.clear()

        if group_end != self._active_bar_end:
            self._active_bar_end = group_end
            self._active_bar_closes = {}

        self._active_bar_closes[end_time] = bar.Close

        if end_time != group_end:
            return

        required_ends = [
            group_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        # Never synthesize or forward-fill an incomplete five-minute bar.
        if not all(timestamp in self._active_bar_closes for timestamp in required_ends):
            self._active_bar_closes.clear()
            return

        five_minute_close = self._active_bar_closes[group_end]
        self._active_bar_closes.clear()

        self._five_minute_closes.append(five_minute_close)
        if len(self._five_minute_closes) < 20:
            return

        closes = list(self._five_minute_closes)
        fast = sum(closes[-5:]) / 5.0
        slow = sum(closes) / 20.0

        bullish_cross = (
            self._previous_fast is not None
            and self._previous_slow is not None
            and self._previous_fast <= self._previous_slow
            and fast > slow
        )

        self._previous_fast = fast
        self._previous_slow = slow

        if not bullish_cross:
            return

        if time(9, 45) <= group_end.time() <= time(14, 30):
            self._try_enter(data, five_minute_close)

