        slow = sum(closes) / 20.0

        bullish_cross = (
            self._previous_fast is not None
            and self._previous_slow is not None
            and self._previous_fast <= self._previous_slow
            and fast > slow
        )

        self._previous_fast = fast
        self._previous_slow = slow

        eligible_time = (
            (bar_end_time.hour, bar_end_time.minute) >= (9, 45)
            and (bar_end_time.hour, bar_end_time.minute) <= (14, 30)
        )

        if bullish_cross and eligible_time:
            self._entry_signal_pending = True

    def _try_enter(self, data: Slice) -> None:
        if self._no_entry_date == self.time.date():
            return

        if self._held_contract is not None and self.portfolio[
            self._held_contract
        ].invested:
            return

        if self._entry_order_id is not None:
            return

        chain = data.option_chains.get(self.option_symbol)
        if chain is None:
            self.debug("Entry skipped: no SPY option chain in Slice.")
            return

        current_date = self.time.date()
        spy_price = self.securities[self.spy].price
        if spy_price <= 0:
            self.debug("Entry skipped: invalid SPY price.")
            return

        eligible_expiries = sorted(
            {
                contract.expiry.date()
                for contract in chain
                if contract.expiry.date() >= current_date + timedelta(days=7)
            }
        )
        if not eligible_expiries:
            self.debug("Entry skipped: no expiration at least 7 calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        required_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.expiry.date() == selected_expiry
            and contract.right == OptionRight.CALL
            and contract.strike >= required_strike
        ]

        if not candidates:
            self.debug("Entry skipped: no qualifying call at selected expiration.")
            return

        selected = min(candidates, key=lambda c: (c.strike, str(c.symbol)))
        ticket = self.market_order(selected.symbol, 1)
        self._entry_order_id = ticket.order_id

        self.debug(
            f"Entry submitted: {selected.symbol}, expiry {selected_expiry}, "
            f"strike {selected.strike:.2f}."
        )

    def _process_exit(self, data: Slice) -> None:
        if self._held_contract is None:
            return

        if not self.portfolio[self._held_contract].invested:
            return

        if self._exit_order_id is not None:
            return

        if self._entry_price is None or self._entry_price <= 0:
            return

        quote = data.quote_bars.get(self._held_contract)
        if quote is None or quote.bid is None or quote.ask is None:
            self._process_time_stop()
            return

        bid = quote.bid.close
        ask = quote.ask.close

        if bid > 0 and ask > 0:
            midpoint = (bid + ask) / 2.0
            if midpoint >= self._entry_price * 1.50:
                self._submit_exit("profit target")
                return

        self._process_time_stop()

    def _process_time_stop(self) -> None:
        if self._held_contract is None or self._exit_order_id is not None:
            return

        expiration_date = self._held_contract.id.date.date()
        previous_trading_day = self.securities[
            self.spy
        ].exchange.hours.get_previous_trading_day(
            datetime.combine(expiration_date, datetime.min.time())
        ).date()

        if (
            self.time.date() == previous_trading_day
            and self.time.hour == 15
            and self.time.minute == 45
        ):
            self._submit_exit("15:45 pre-expiration time stop")

    def _process_expiration_safety(self) -> None:
        if self._held_contract is None:
            return

        if not self.portfolio[self._held_contract].invested:
            return

        expiration_date = self._held_contract.id.date.date()
        if self.time.date() >= expiration_date:
            self._no_entry_date = self.time.date()
            if self._exit_order_id is None:
                self._submit_exit("expiration safety")
                self._expiration_exit_requested = True

    def _submit_exit(self, reason: str) -> None:
        if self._held_contract is None:
            return

        for ticket in self.transactions.get_open_order_tickets(self._held_contract):
            ticket.cancel(f"Replacing open exit order: {reason}")

        quantity = -self.portfolio[self._held_contract].quantity
        if quantity == 0:
            return

        ticket = self.market_order(self._held_contract, quantity)
        self._exit_order_id = ticket.order_id
        self.debug(f"Exit submitted ({reason}): {self._held_contract}.")

    def on_order_event(self, order_event: OrderEvent) -> None:
        if (
            order_event.order_type == OrderType.OPTION_EXERCISE
            or "assign" in order_event.message.lower()
            or "exercise" in order_event.message.lower()
        ):
            self.debug(
                f"Unexpected option exercise/assignment: "
                f"{order_event.symbol} - {order_event.message}"
            )

        if order_event.order_id == self._entry_order_id:
            if (
                order_event.status in (OrderStatus.PARTIALLY_FILLED, OrderStatus.FILLED)
                and order_event.fill_quantity > 0
            ):
                self._held_contract = order_event.symbol
                self._entry_price = order_event.fill_price
                self.debug(
                    f"Entry filled: {order_event.symbol} at "
                    f"{order_event.fill_price:.2f}."
                )

            if order_event.status in (
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID,
            ):
                self._entry_order_id = None

        if order_event.order_id == self._exit_order_id:
            if (
                order_event.status in (OrderStatus.PARTIALLY_FILLED, OrderStatus.FILLED)
                and order_event.fill_quantity < 0
            ):
                self.debug(
                    f"Exit filled: {order_event.symbol} at "
                    f"{order_event.fill_price:.2f}."
                )

            if order_event.status in (
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID,
            ):
                self._exit_order_id = None
                if (
                    self._held_contract is not None
                    and not self.portfolio[self._held_contract].invested
                ):
                    self._held_contract = None
                    self._entry_price = None
                    self._expiration_exit_requested = False
